const esc = (value='') => String(value).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const slugify = value => value.toLowerCase().replaceAll('&','and').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
const url = path => SITE_URL + (path === '/' ? '/' : path.replace(/\/$/,'') + '/');
const ld = graph => '<script type="application/ld+json">' + JSON.stringify({'@context':'https://schema.org','@graph':graph}).replaceAll('<','\\u003c') + '</script>';
const source = (label, href) => '<a class="source" href="' + href + '" rel="nofollow">' + esc(label) + ' <span>' + accessed + '</span></a>';

