function baseGraph(page) {
  const graph = [
    {'@type':'Organization','@id':SITE_URL+'/#organization','name':'Style BFF','alternateName':'BingeTry','url':SITE_URL+'/','logo':SITE_URL+'/assets/logo_new.webp','sameAs':[APP_STORE_URL,PLAY_STORE_URL]},
    {'@type':'WebSite','@id':SITE_URL+'/#website','name':'Style BFF','url':SITE_URL+'/','publisher':{'@id':SITE_URL+'/#organization'},'potentialAction':{'@type':'SearchAction','target':SITE_URL+'/blog/?q={search_term_string}','query-input':'required name=search_term_string'}},
    {'@type':'BreadcrumbList','itemListElement':page.path.split('/').filter(Boolean).map((name,index,list)=>({'@type':'ListItem','position':index+1,'name':name.replaceAll('-',' '),'item':SITE_URL+'/'+list.slice(0,index+1).join('/')+'/'}))}
  ];
  if (page.schema) {
    const isEditorialArticle = page.editorial && ['Article','BlogPosting'].includes(page.schema['@type']);
    graph.push(isEditorialArticle ? {
      ...page.schema,
      author: {'@id':SITE_URL+'/#organization'},
      publisher: {'@id':SITE_URL+'/#organization'},
      mainEntityOfPage: {'@id':url(page.path)},
      inLanguage: 'en'
    } : page.schema);
  }
  if (page.faq?.length) graph.push({'@type':'FAQPage','mainEntity':page.faq.map(item=>({'@type':'Question','name':item[0],'acceptedAnswer':{'@type':'Answer','text':item[1]}}))});
  return graph;
}

function head(page) {
  const title = page.title.length > 60 ? page.title.slice(0,57) + '…' : page.title;
  const description = page.description.length > 155 ? page.description.slice(0,152) + '…' : page.description;
  const noindex = page.status === 'outline' ? '<meta name="robots" content="noindex,follow" />' : '';
  return '<!doctype html><html lang="en"><head><meta charset="UTF-8"/><meta name="viewport" content="width=device-width,initial-scale=1.0"/><title>' + esc(title) + '</title><meta name="description" content="' + esc(description) + '"/><link rel="canonical" href="' + url(page.path) + '"/><link rel="alternate" hreflang="en" href="' + url(page.path) + '"/><link rel="alternate" hreflang="x-default" href="' + url(page.path) + '"/><meta property="og:type" content="website"/><meta property="og:title" content="' + esc(title) + '"/><meta property="og:description" content="' + esc(description) + '"/><meta property="og:url" content="' + url(page.path) + '"/><meta property="og:image" content="' + SITE_URL + '/assets/og-style-bff.png"/><meta name="twitter:card" content="summary_large_image"/><meta name="twitter:title" content="' + esc(title) + '"/><meta name="twitter:description" content="' + esc(description) + '"/><meta name="twitter:image" content="' + SITE_URL + '/assets/og-style-bff.png"/><meta name="apple-itunes-app" content="app-id=6767003047, app-argument=' + url(page.path) + '"/><link rel="alternate" href="android-app://com.bingetry.vitualtryon/https/' + new URL(SITE_URL).hostname + page.path + '"/><link rel="stylesheet" href="/styles.css"/><link rel="stylesheet" href="/pages.css"/><link rel="icon" type="image/svg+xml" href="/favicon.svg"/>' + noindex + '</head><body>';
}

function cta(page) {
  return '<aside class="page-cta"><div><p class="eyebrow">Your next outfit</p><h2>See it on you.</h2><p>Search <strong>Style BFF</strong> on the App Store or Google Play.</p>' + storeButtons(slugify(page.h1)) + '</div><a class="qr-placeholder" href="/download/" aria-label="Open the Style BFF download page"><img src="/assets/qr-download.png" width="168" height="168" loading="lazy" decoding="async" alt="QR code for the Style BFF download page"/></a></aside>';
}

function sectionMarkup(sections=[]) {
  return sections.map(item => '<section class="article-section"><h2>' + esc(item[0]) + '</h2>' + (Array.isArray(item[1]) ? '<ul>' + item[1].map(x=>'<li>'+x+'</li>').join('') + '</ul>' : '<p>' + item[1] + '</p>') + '</section>').join('');
}

function faqMarkup(faq=[]) {
  if (!faq.length) return '';
  return '<section class="article-section"><h2>What else should you know?</h2><div class="faq-list">' + faq.map(item=>'<details><summary>'+esc(item[0])+'</summary><p>'+item[1]+'</p></details>').join('') + '</div></section>';
}

function pageBody(page) {
  const image = page.image ? '<figure class="page-visual"><img src="' + page.image + '" alt="' + esc(page.imageAlt || page.h1) + '" width="1024" height="1024" decoding="async" fetchpriority="high"/></figure>' : '';
  const badge = page.status === 'outline' ? '<span class="status-badge">Editorial outline</span>' : '';
  const editorial = page.editorial && page.status !== 'outline' ? '<p class="editorial-meta">Written and maintained by the Style BFF editorial team · <a href="/editorial-policy/">Editorial standards</a></p>' : '';
  const extra = page.html || '';
  return nav + '<main id="main"><article class="page-shell"><header class="page-hero"><div><p class="eyebrow">' + esc(page.kicker || page.primaryKeyword || 'Style BFF guide') + '</p>' + badge + '<h1>' + esc(page.h1) + '</h1><p class="answer-first">' + page.answer + '</p><p class="updated">Last updated ' + LAST_UPDATED + '</p>' + editorial + storeButtons(slugify(page.h1)) + '</div>' + image + '</header><div class="article-body">' + (page.cite ? '<aside class="cite-block">' + page.cite + '</aside>' : '') + sectionMarkup(page.sections) + extra + faqMarkup(page.faq) + '</div>' + cta(page) + '</article></main>' + footer + ld(baseGraph(page)) + '<script src="/site.js" defer></script></body></html>';
}

async function writeRoute(page, group='pages') {
  const isEditorialRoute = group === 'blog' || page.path.startsWith('/compare/');
  const renderedPage = {...page, editorial: page.editorial ?? isEditorialRoute};
  const clean = renderedPage.path === '/' ? '' : renderedPage.path.replace(/^\/|\/$/g,'');
  const file = clean ? join(out, clean, 'index.html') : join(out, 'index.html');
  await mkdir(dirname(file), {recursive:true});
  await writeFile(file, renderedPage.path === '/' ? renderedPage.html : head(renderedPage) + pageBody(renderedPage), 'utf8');
  allPaths.add(renderedPage.path);
  if (renderedPage.status !== 'outline' && !renderedPage.noSitemap) sitemapGroups[group].push(renderedPage.path);
}

