function comparisonHtml(slug, name, href) {
  const evidence = comparisonEvidence[slug];
  if (!evidence) return '<p>'+source(name+' official product source',href)+'</p>';
  return '<div class="table-wrap"><table><caption>Style BFF and '+esc(name)+' at a glance</caption><thead><tr><th>Decision point</th><th>Style BFF</th><th>'+esc(name)+'</th></tr></thead><tbody><tr><th>Documented focus</th><td>Style Profile guidance, outfits from a digital wardrobe, occasion help and supported-link try-on on your own photo.</td><td>'+esc(evidence[0])+'</td></tr><tr><th>Best considered when</th><td>You want to connect what suits you, what you own, a real plan and a saved look in one styling workflow.</td><td>Its documented workflow matches the job you repeat most.</td></tr><tr><th>Check before choosing</th><td>Supported links, wardrobe setup and try-on expectations.</td><td>Current platform availability, pricing and privacy terms on its official source.</td></tr></tbody></table></div><p>'+source(name+' official product source',evidence[1])+'</p>';
}

